"use client";
import { useState, useEffect, useRef, type FormEvent, type ReactNode } from "react";
import { Utensils, Palette, Store, ClipboardList, Settings, Plus, ArrowUpRight, Check, Link2, Copy, LogOut, Search, ImagePlus, Trash2, Pencil, Eye, Globe, Save, Clock, ArrowRight, ArrowLeft, Upload, X, CheckCircle2, MessageCircle, Package, Pizza, RefreshCw, CreditCard, AlertCircle, Pause, Menu as MenuIcon, Sparkles, Calculator, TrendingUp, ChevronDown, Star, ShoppingBag } from "lucide-react";
import { Brand, Modal, MiniMenu, ThemeCards, Spinner } from "./ui";
import Menu from "./menu";
import AiImport from "./ai-import";
import DailyPromotions from "./daily-promotions";
import StudioChat from "./studio-chat";
import {BillingControls} from "./billing-controls";
import { themes, restaurantSchema, defaultRestaurant, demoRestaurant, slugify, slugSchema, phoneNumber, money, asCents, type RestaurantData, type RestaurantRecord, type Product, type ThemeId, type OrderSummary } from "@/lib/domain";
import { availableProduct } from "@/lib/menu-sales";
import type { SalesSummary } from "@/lib/sales";
import {orderStatuses as statuses} from "@/lib/order-policy";
import {OrderDetails,OrderAlerts,PaymentBadge,nextOrderAction,actionLabels,type OrderRecord,type ActionDetails} from "./order-admin";
import PwaSetup from "./pwa-setup";
import DeliveryApprovals from "./delivery-approvals";
import DeliveryAreas from "./delivery-areas";

const navigation = [
  { id: "overview", label: "Pedidos", icon: ClipboardList },
  { id: "menu", label: "Cardápio", icon: Pizza },
  { id: "store", label: "Pizzaria", icon: Store },
  { id: "studio", label: "Criar com IA", icon: Sparkles },
] as const;
type ApiResult = { restaurant: RestaurantRecord; orders: OrderRecord[]; order: OrderRecord; sales: SalesSummary; error?: string };
async function api(path: string, method = "GET", body?: unknown): Promise<ApiResult> {
  let res:Response;
  try{
    const csrf=method!=="GET"?await fetch("/api/auth/config",{cache:"no-store",signal:AbortSignal.timeout(20000)}).then(r=>r.json() as Promise<{csrf:string}>).then(v=>v.csrf):"";
    res=await fetch(path, { method,cache:"no-store",signal:AbortSignal.timeout(20000), headers: body ? { "Content-Type": "application/json", "x-pedido-csrf":csrf } : undefined, body: body ? JSON.stringify(body) : undefined });
  }catch(error){
    if(error instanceof Error&&["TimeoutError","AbortError"].includes(error.name))throw Error("A conexão demorou. Reabra o painel para conferir se a alteração foi salva antes de tentar novamente.");
    if(error instanceof TypeError)throw Error("A alteração não foi confirmada. Confira sua conexão e tente novamente.");throw error;
  }
  const result = await res.json() as ApiResult;
  if (!res.ok) throw new Error(result.error || "Não foi possível concluir a ação.");
  return result;
}

export default function Dashboard({ initialRestaurants, user, signOutUrl, initialTheme = "editorial", initialPlan = "essencial", startNew = false, initialRestaurantId, initialOrderId }: {
  initialRestaurants: RestaurantRecord[]; user: { name: string; email: string;admin?:boolean }; signOutUrl: string; initialTheme?: ThemeId; initialPlan?: string; startNew?: boolean;initialRestaurantId?:string;initialOrderId?:string;
}) {
  const [restaurants, setRestaurants] = useState(initialRestaurants);
  const firstRestaurant=initialRestaurants.find(r=>r.id===initialRestaurantId)||initialRestaurants[0];
  const [activeId, setActiveId] = useState(firstRestaurant?.id || "");
  const [draft, setDraft] = useState<RestaurantData>(firstRestaurant ? restaurantSchema.parse(JSON.parse(firstRestaurant.data)) : defaultRestaurant("Sua pizzaria"));
  const [requestedOrder,setRequestedOrder]=useState(initialOrderId||"");
  const [tab, setTab] = useState("overview");
  const [dirty, setDirty] = useState(false), [saving, setSaving] = useState(false),[readerActive,setReaderActive]=useState(false);
  const [error, setError] = useState(""), [toast, setToast] = useState("");
  const [firstRun,setFirstRun]=useState<{restaurantId:string;idea:string}|null>(null);
  const [createOpen, setCreateOpen] = useState(startNew || !initialRestaurants.length), [previewOpen, setPreviewOpen] = useState(false), [shareOpen, setShareOpen] = useState(false);
  const [productEdit, setProductEdit] = useState<Product | null>(null), [mobileNav, setMobileNav] = useState(false);
  const [catalogSearch, setCatalogSearch] = useState(""), [filterCategory, setFilterCategory] = useState("all"), [categoryName, setCategoryName] = useState("");
  const [orderList, setOrderList] = useState<OrderRecord[]>([]), [sales, setSales] = useState<SalesSummary | null>(null), [ordersLoading, setOrdersLoading] = useState(false);
  const [lastSync,setLastSync]=useState(0),[ordersOffline,setOrdersOffline]=useState(false);
  const [orderFilter, setOrderFilter] = useState("work"), [orderDetail, setOrderDetail] = useState<OrderRecord | null>(null), [updatingOrder, setUpdatingOrder] = useState("");
  const active = restaurants.find(r => r.id === activeId);
  const openNotification=useRef<(url:string)=>void>(()=>{});
  openNotification.current=async(value)=>{try{if(savingRef.current)return;const url=new URL(value,location.origin);if(url.origin!==location.origin||url.pathname!=="/app")return;const shop=url.searchParams.get("loja"),order=url.searchParams.get("pedido");if(shop&&!restaurants.some(r=>r.id===shop))return;if(shop&&shop!==activeId){if(dirty&&!await save())return;setActiveId(shop);}setTab("overview");if(order)setRequestedOrder(order);}catch{}};
  useEffect(()=>{const handler=(event:MessageEvent)=>{if(event.data?.type==="OPEN_NOTIFICATION"&&typeof event.data.url==="string")openNotification.current(event.data.url);};navigator.serviceWorker?.addEventListener("message",handler);return()=>navigator.serviceWorker?.removeEventListener("message",handler);},[]);
  useEffect(()=>{if(!requestedOrder)return;const found=orderList.find(row=>row.id===requestedOrder);if(found){setOrderDetail(found);setRequestedOrder("");}},[requestedOrder,orderList]);
  const savingRef=useRef(false);
  const dirtyRef = useRef(dirty), activeIdRef = useRef(activeId), ordersRequest = useRef(0),ordersBusy=useRef(new Set<string>());
  dirtyRef.current = dirty||saving||readerActive; activeIdRef.current = activeId;

  useEffect(() => {
    const row = restaurants.find(r => r.id === activeId);
    if (row) { setDraft(restaurantSchema.parse(JSON.parse(row.data))); setDirty(false); }
    setOrderList([]);setLastSync(0);setOrdersOffline(false); setSales(null); setOrderDetail(null); setError(""); setFilterCategory("all"); setCatalogSearch("");
  }, [activeId]);
  useEffect(() => {
    const before = (event: BeforeUnloadEvent) => { if (dirtyRef.current) { event.preventDefault(); event.returnValue = ""; } };
    window.addEventListener("beforeunload", before); return () => window.removeEventListener("beforeunload", before);
  }, []);
  useEffect(() => { if (!toast) return; const timer = setTimeout(() => setToast(""), 4000); return () => clearTimeout(timer); }, [toast]);
  useEffect(() => {
    if (!activeId) return;
    loadOrders();
    const timer = setInterval(() => { loadOrders(true); }, 8000);
    return () => clearInterval(timer);
  }, [activeId]);

  function change(patch: Partial<RestaurantData>) { setDraft(old => ({ ...old, ...patch })); setDirty(true); setError(""); }
  function updateRecord(record: RestaurantRecord) { setRestaurants(old => old.map(r => r.id === record.id ? record : r)); }
  async function save(): Promise<RestaurantRecord | null> {
    if (!active||savingRef.current) return null; if (!dirty) return active;
    savingRef.current=true;setSaving(true); setError("");
    try {
      const result = await api(`/api/restaurants/${active.id}`, "PUT", { data: draft, revision: active.revision });
      updateRecord(result.restaurant); setDraft(restaurantSchema.parse(JSON.parse(result.restaurant.data))); setDirty(false); setToast("Rascunho salvo."); return result.restaurant;
    } catch (e) { setError(e instanceof Error ? e.message : "Não foi possível salvar."); return null; }
    finally { savingRef.current=false;setSaving(false); }
  }
  async function importMenu(patch:Partial<RestaurantData>){
    if(!active||savingRef.current)throw Error("Aguarde o salvamento atual antes de importar.");
    const next=restaurantSchema.parse({...draft,...patch});
    savingRef.current=true;setSaving(true);setError("");
    try{
      const result=await api(`/api/restaurants/${active.id}`,"PUT",{data:next,revision:active.revision});
      updateRecord(result.restaurant);setDraft(restaurantSchema.parse(JSON.parse(result.restaurant.data)));setDirty(false);
      setToast("Produtos importados e rascunho salvo. Publique quando estiver pronto.");
    }catch(error){throw Error(error instanceof Error?error.message:"Não foi possível salvar a importação. Sua leitura foi mantida.");}
    finally{savingRef.current=false;setSaving(false);}
  }
  const storeReady = phoneNumber(draft.whatsapp).length >= 12 && phoneNumber(draft.whatsapp).length <= 15 && (draft.deliveryEnabled || draft.pickupEnabled) && (!draft.pickupEnabled || !!draft.address.trim()) && draft.payments.length > 0;
  const menuReady = draft.products.some(availableProduct);
  async function publish(value = true) {
    if(savingRef.current)return;
    if (value && (!storeReady || !menuReady)) {
      setError(!storeReady ? "Complete o WhatsApp, a entrega ou retirada e as formas de pagamento para publicar." : "Cadastre ao menos um produto disponível com preço para publicar.");
      setTab(!storeReady ? "store" : "menu"); return;
    }
    const wasPublished = active?.published, row = await save(); if (!row) return;
    savingRef.current=true;setSaving(true); setError("");
    try {
      const result = await api(`/api/restaurants/${row.id}/publish`, "POST", { revision: row.revision, published: value });
      updateRecord(result.restaurant);
      setToast(value ? "Cardápio atualizado. Seus clientes já veem as alterações." : "Publicação pausada.");
      if (value && !wasPublished) { setShareOpen(true); setTab("overview"); }
    } catch (e) { setError(e instanceof Error ? e.message : "Não foi possível publicar."); }
    finally { savingRef.current=false;setSaving(false); }
  }
  async function switchRestaurant(id: string) { if (id === activeId||savingRef.current) return; if (dirty && !await save()) return; setActiveId(id); setTab("overview"); }
  async function loadOrders(silent = false) {
    if (!activeId||ordersBusy.current.has(activeId)) return; const id = activeId, request = ++ordersRequest.current;ordersBusy.current.add(id);
    if (!silent) setOrdersLoading(true);
    try {
      const body = await api(`/api/restaurants/${id}/orders`);
      if (activeIdRef.current === id && request === ordersRequest.current) { setOrderList(old=>body.orders.map(next=>{const previous=old.find(o=>o.id===next.id);return previous&&previous.version>next.version?previous:next;})); setSales(body.sales);setLastSync(Date.now());setOrdersOffline(false);setOrderDetail(old=>{if(!old)return null;const next=body.orders.find(o=>o.id===old.id);return next&&next.version>=old.version?next:old;}); }
    } catch (e) { if(activeIdRef.current===id)setOrdersOffline(true);if (!silent && activeIdRef.current === id) setError(e instanceof Error ? e.message : "Não foi possível carregar os pedidos."); }
    finally {ordersBusy.current.delete(id); if (activeIdRef.current === id && request === ordersRequest.current) setOrdersLoading(false); }
  }
  async function updateOrder(order:OrderRecord,details:ActionDetails) {
    if(updatingOrder)return false;const restaurantId=activeId;setUpdatingOrder(order.id);setError("");
    try {const body=await api(`/api/restaurants/${restaurantId}/orders`,"PATCH",{orderId:order.id,version:order.version,...details});
      if(activeIdRef.current!==restaurantId)return false;
      setOrderList(old=>old.map(o=>o.id===order.id?body.order:o));setOrderDetail(old=>old?.id===order.id?body.order:old);
      setToast(details.action==="confirm"?"Pedido aprovado. O cliente já pode acompanhar o prazo.":"Pedido atualizado para o cliente.");await loadOrders(true);return true;
    }catch(e){if(activeIdRef.current===restaurantId){setError(e instanceof Error?e.message:"Não foi possível atualizar.");await loadOrders(true);}return false;}
    finally {setUpdatingOrder("");}
  }
  function editProduct(kind: "pizza" | "drink" | "combo" = "pizza") {
    const match = kind === "drink" ? /bebida|refrigerante|suco/i : kind === "combo" ? /combo/i : /pizza/i;
    let category = draft.categories.find(c => match.test(c.name));
    if (!category && draft.categories.length < 20) {
      category = { id: crypto.randomUUID(), name: kind === "drink" ? "Bebidas" : kind === "combo" ? "Combos" : "Pizzas" };
      change({ categories: [...draft.categories, category] });
    }
    setProductEdit({ id: crypto.randomUUID(), categoryId: category?.id || draft.categories[0].id, name: "", description: "", kind: kind === "pizza" ? "pizza" : "simple", image: "", price: 0, sizes: { p: 0, m: 0, g: 0 }, enabled: true, featured: kind === "combo" });
  }
  function saveProduct(product: Product) {
    change({ products: draft.products.some(p => p.id === product.id) ? draft.products.map(p => p.id === product.id ? product : p) : [...draft.products, product] });
    setProductEdit(null); setToast(active?.published ? "Produto no rascunho. Use Salvar e atualizar para colocar no ar." : "Produto cadastrado. Publique quando o cardápio estiver pronto.");
  }
  async function copyLink() {
    if (!active) return; try { await navigator.clipboard.writeText(`${location.origin}/p/${active.slug}`); setToast("Link copiado."); } catch { setShareOpen(true); }
  }
  const visibleProducts = draft.products.filter(p => (filterCategory === "all" || p.categoryId === filterCategory) && `${p.name} ${p.description}`.toLowerCase().includes(catalogSearch.toLowerCase()));
  const working = orderList.filter(o => ["awaiting_payment", "awaiting", "confirmed", "preparing", "out_for_delivery"].includes(o.status));
  const shownOrders = orderList.filter(o => orderFilter === "all" || (orderFilter === "work" ? ["awaiting_payment", "awaiting", "confirmed", "preparing", "out_for_delivery"].includes(o.status) : ["delivered", "canceled"].includes(o.status)));
  const sectionName = navigation.find(n => n.id === tab)?.label;

  return <div className="dashboard simple-dashboard"><PwaSetup hasUnsaved={dirty||saving||readerActive||!!productEdit||createOpen||tab==="studio"}/>
    <aside className={`sidebar ${mobileNav ? "visible" : ""}`}>
      <div className="sidebar-brand"><Brand /><button className="icon-btn mobile-nav" aria-label="Fechar menu" onClick={() => setMobileNav(false)}><X size={20} /></button></div>
      <div className="shop-picker"><label><span>SUA PIZZARIA</span><select value={activeId} disabled={saving} onChange={e => switchRestaurant(e.target.value)}>{!restaurants.length && <option value="">Criar minha pizzaria</option>}{restaurants.map(r => <option key={r.id} value={r.id}>{r.name}</option>)}</select></label><span className={`shop-status ${active?.published ? "live" : ""}`}><i />{active?.published ? "Cardápio no ar" : "Ainda não publicado"}</span></div>
      <nav aria-label="Painel da pizzaria">{navigation.map(item => <button key={item.id} className={tab === item.id ? "active" : ""} aria-current={tab === item.id ? "page" : undefined} onClick={() => { setTab(item.id); setMobileNav(false); }}><item.icon size={20} />{item.label}{item.id === "overview" && working.length > 0 && <span>{working.length}</span>}</button>)}</nav>
      <div className="sidebar-bottom"><a href="/calculadora" className="sidebar-calculator"><Calculator size={19}/><span>Preço e lucro<small>Calculadora grátis · sem login</small></span><ArrowUpRight size={15}/></a><details className="sidebar-more"><summary>Conta e outras opções <ChevronDown size={15}/></summary><button className="sidebar-link" disabled={saving} onClick={() => setCreateOpen(true)}><Plus size={17}/>Nova pizzaria</button><a href="/conta" className="sidebar-link"><Settings size={17}/>Minha conta</a>{user.admin&&<a href="/admin" className="sidebar-link"><Settings size={17}/>Administração</a>}<a href={signOutUrl} target="_top" className="sidebar-link"><LogOut size={17}/>Sair</a></details><div className="user-profile"><span>{user.name.slice(0,1).toUpperCase()}</span><div><strong>{user.name.includes("@")?user.name.split("@")[0]:user.name}</strong><small>{user.email}</small></div></div></div>
    </aside>
    {mobileNav && <button className="sidebar-scrim" aria-label="Fechar menu" onClick={() => setMobileNav(false)} />}
    <div className="dashboard-body">
      <header className="dashboard-header"><div><button className="icon-btn mobile-nav" aria-label="Abrir menu do painel" onClick={() => setMobileNav(true)}><MenuIcon size={21} /></button><span className="breadcrumb">pedido.on <span>/</span> <strong>{sectionName}</strong></span></div><div className="dashboard-header-actions"><span className={`save-status ${dirty ? "dirty" : ""}`}><i />{saving ? "Salvando…" : dirty ? "Rascunho alterado" : active?.published && active.revision !== active.liveRevision ? "Rascunho não publicado" : "Tudo salvo"}</span><button className="btn outline small" disabled={!active || saving} onClick={() => setPreviewOpen(true)}><Eye size={17} />Ver cardápio</button><button className="btn primary small" disabled={!active || saving || (active.published && !dirty && active.revision === active.liveRevision)} onClick={() => publish()}>{saving ? <Spinner /> : <Globe size={17} />}{active?.published ? "Atualizar" : "Publicar"}</button></div></header>
      <main className="dashboard-content">
        {error && <div className="error-banner" role="alert"><AlertCircle size={20} /><p>{error}</p><button className="icon-btn" aria-label="Fechar aviso" onClick={() => setError("")}><X size={17} /></button></div>}
        {!active ? <div className="dashboard-welcome"><span className="brand-icon"><Pizza /></span><span className="eyebrow">COMECE PELO ESSENCIAL</span><h1>Seu próximo pedido<br />começa aqui.</h1><p>Nome, WhatsApp e seus sabores. Monte o cardápio e compartilhe o link com seus clientes.</p><button className="btn primary" onClick={() => setCreateOpen(true)}>Criar meu cardápio <Plus size={18} /></button></div> : <>
          <OrderAlerts key={active.id} orders={orderList} loaded={!!lastSync} onOpen={()=>setTab("overview")}/>{ordersOffline&&<div className="error-banner" role="alert"><AlertCircle size={20}/><p>Conexão interrompida. Os pedidos podem estar desatualizados. Use Atualizar para tentar novamente.</p></div>}<div className="dashboard-title"><div><span className="eyebrow">{tab === "overview" ? draft.name : sectionName}</span><h1>{tab === "overview" ? "Pedidos" : tab === "menu" ? "Cardápio" : tab === "studio" ? "Criar com IA" : "Sua pizzaria"}</h1><p>{tab === "overview" ? "Acompanhe cada pedido, do pagamento à entrega." : tab === "menu" ? "Seus sabores, tamanhos e preços." : tab === "studio" ? "Visual, textos e imagens em um só lugar." : "Contato, entrega e pagamento."}</p></div>{tab === "overview" && <button className="btn outline small" disabled={ordersLoading} onClick={() => loadOrders()}>{ordersLoading ? <Spinner /> : <RefreshCw size={17} />}Atualizar</button>}</div>
          {tab === "overview" && <>
            <DeliveryApprovals key={active.id} restaurantId={active.id}/>
            {!active.published && <section className="setup-simple panel-card"><div className="panel-heading"><div><span className="eyebrow">SEU PRIMEIRO CARDÁPIO</span><h2>Três passos para começar.</h2></div><span className="pill">{Number(storeReady) + Number(menuReady)} de 3</span></div><div className="setup-simple-steps"><button onClick={() => setTab("store")}><span className={storeReady ? "done" : ""}>{storeReady ? <Check size={18} /> : "1"}</span><b>Configure sua loja</b><small>WhatsApp, entrega e pagamento</small><ArrowRight size={18} /></button><button onClick={() => setTab("menu")}><span className={menuReady ? "done" : ""}>{menuReady ? <Check size={18} /> : "2"}</span><b>Cadastre os sabores</b><small>Uma pizza com preço já basta</small><ArrowRight size={18} /></button><button disabled={saving} onClick={() => publish()}><span>3</span><b>Publique e compartilhe</b><small>Seu link pronto para receber pedidos</small><ArrowRight size={18} /></button></div></section>}
            <div className="dashboard-stats sales-stats"><article className="sales-main"><span><TrendingUp size={19} />Vendido hoje</span><strong>{sales ? money(sales.value) : "—"}<small>{sales ? `${sales.confirmed} ${sales.confirmed === 1 ? "pedido confirmado" : "pedidos confirmados"}` : "Carregando vendas…"}</small></strong></article><article><span><ShoppingBag size={19} />Valor médio por pedido</span><strong>{sales ? money(sales.average) : "—"}<small>Somente pedidos confirmados</small></strong></article><article><span><Clock size={19} />A confirmar hoje</span><strong>{sales ? sales.pending : "—"}<small>Confira os pedidos e comprovantes</small></strong></article></div>
            <p className="sales-caption">Hoje em São Paulo · valor dos pedidos após descontos, incluindo entrega. Pedidos pendentes e cancelados ficam fora das vendas.</p>
            <div className="sales-workspace"><section className="panel-card daily-orders"><div className="panel-heading"><h2>Seus pedidos</h2><span className="live-update"><i />Atualiza a cada 8 s</span></div><div className="orders-filters">{[{ id: "work", label: "Para fazer", count: working.length }, { id: "done", label: "Finalizados", count: orderList.length - working.length }, { id: "all", label: "Todos", count: orderList.length }].map(item => <button key={item.id} className={orderFilter === item.id ? "active" : ""} aria-pressed={orderFilter === item.id} onClick={() => setOrderFilter(item.id)}>{item.label}<span>{item.count}</span></button>)}</div>
              {shownOrders.map(order => {
                const summary = JSON.parse(order.data) as OrderSummary, next = nextOrderAction(order);
                return <article className="simple-order" key={order.id}><div className="simple-order-heading"><div><span className={`status-tag ${order.status}`}>{statuses[order.status]}</span><h3>{order.customer} <small>#{order.id.slice(0, 8).toUpperCase()}</small></h3><p>{new Date(order.createdAt).toLocaleString("pt-BR", { timeZone: "America/Sao_Paulo", day: "2-digit", month: "2-digit", hour: "2-digit", minute: "2-digit" })} · {summary.method === "delivery" ? "Entrega" : "Retirada"}</p></div><strong>{money(order.total)}</strong></div><PaymentBadge order={order}/><p className="order-items-line">{summary.items.map(line => `${line.quantity}× ${line.label}`).join(" · ")}</p><div className="simple-order-actions"><button className="btn outline small" onClick={() => setOrderDetail(order)}>Detalhes</button><a className="order-whatsapp" href={`https://wa.me/${order.phone}`} target="_blank" rel="noopener noreferrer" aria-label={`Falar com ${order.customer} no WhatsApp`}><MessageCircle size={19} />WhatsApp</a>{next && <button className="btn primary small" disabled={!!updatingOrder} onClick={() => next==="confirm"?setOrderDetail(order):updateOrder(order,{action:next})}>{updatingOrder === order.id ? <Spinner /> : <Check size={16} />}{actionLabels[next]}</button>}</div></article>;
              })}
              {!shownOrders.length && <div className="empty-orders"><ClipboardList size={34} /><h3>{ordersLoading ? "Buscando pedidos…" : orderFilter === "work" ? "Tudo em dia por aqui." : "Ainda não há pedidos aqui."}</h3><p>{active.published ? "Compartilhe o cardápio para seus clientes começarem a pedir." : "Publique o cardápio para começar a receber pedidos."}</p><button className="btn outline small" onClick={() => active.published ? setShareOpen(true) : publish()} disabled={saving}><Link2 size={17} />{active.published ? "Compartilhar cardápio" : "Publicar meu cardápio"}</button></div>}
              <small className="orders-history-note">Histórico: últimos 100 pedidos. As vendas de hoje consideram todos os pedidos do dia. Confira o recebimento no banco antes de aprovar um pedido com Pix antecipado.</small>
            </section><aside className="sales-side"><section className="share-panel simple-share"><span className="share-panel-icon"><Link2 size={25} /></span><div><h2>Seu link vende com você.</h2><p>Coloque no Instagram, nas embalagens e no WhatsApp.</p><div className="url-display"><span>/p/{active.slug}</span><button className="icon-btn" aria-label="Copiar link" onClick={copyLink}><Copy size={17} /></button></div><button className="btn dark full" onClick={() => setShareOpen(true)}><ArrowUpRight size={17} />Compartilhar cardápio</button>{!active.published && <small>Disponível aos clientes depois de publicar.</small>}</div></section><section className="panel-card selling-tip"><span className="eyebrow">PARA COMPLETAR O PEDIDO</span><h2>Pizza + bebida.<br />Uma escolha fácil.</h2><p>Cadastre bebidas e um combo com preço definido por você. O cardápio sugere a bebida antes da finalização.</p><button className="text-button" onClick={() => { setTab("menu"); editProduct("combo"); }}>Montar um combo <ArrowRight size={17} /></button></section><button className="preview-shortcut" onClick={() => setPreviewOpen(true)}><Eye size={20} /><span>Veja como o cliente pede<small>Abrir prévia do seu cardápio</small></span><ArrowUpRight size={18} /></button></aside></div>
          </>}
          <fieldset className="editor-fieldset" disabled={saving}>
            {tab === "menu" && <>
              <AiImport key={active.id} restaurantId={active.id} draft={draft} onImport={importMenu} onActivityChange={setReaderActive}/>
              {draft.products.length>0&&<div className="catalog-actions"><p>{draft.products.length} {draft.products.length===1?"produto cadastrado":"produtos cadastrados"}</p><button className="btn primary" onClick={()=>editProduct("pizza")}><Plus size={18}/>Adicionar produto</button></div>}
              {draft.products.length>0&&<div className="catalog-toolbar"><div className="input-search"><Search size={18} /><input value={catalogSearch} onChange={e => setCatalogSearch(e.target.value)} placeholder="Buscar produto" aria-label="Buscar produtos" /></div><select value={filterCategory} onChange={e => setFilterCategory(e.target.value)} aria-label="Filtrar categoria"><option value="all">Todas as categorias</option>{draft.categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}</select><span className="catalog-count">{draft.products.filter(availableProduct).length} disponíveis</span></div>}
              <section className="panel-card product-table-panel"><div className="product-table-head"><span>PRODUTO</span><span>CATEGORIA</span><span>PREÇO</span><span>DISPONÍVEL</span><span /></div>{visibleProducts.map(product => <div className="product-table-row" key={product.id}><button className="product-cell" onClick={() => setProductEdit(product)}><span className="table-product-image">{product.image ? <img src={product.image} alt="" /> : <Pizza size={23} />}</span><div><b>{product.name}</b><small>{product.kind === "pizza" ? "Pizza" : "Produto ou combo"}{product.featured && <><Star size={11} />Destaque</>}</small></div></button><span>{draft.categories.find(c => c.id === product.categoryId)?.name}</span><span className="table-price">{product.kind === "pizza" ? <><small>A partir de</small>{money(Math.min(...Object.values(product.sizes).filter(n => n > 0)) || 0)}</> : money(product.price)}</span><button className={`toggle ${product.enabled ? "on" : ""}`} role="switch" aria-checked={product.enabled} aria-label={`Disponibilidade de ${product.name}`} onClick={() => change({ products: draft.products.map(row => row.id === product.id ? { ...row, enabled: !row.enabled } : row) })}><span /></button><button className="icon-btn" aria-label={`Editar ${product.name}`} onClick={() => setProductEdit(product)}><Pencil size={17} /></button></div>)}{!visibleProducts.length && <div className="table-empty">{!draft.products.length&&<img src="/assets/pizza.webp" alt="Pizza artesanal" className="empty-pizza-photo"/>}<h3>{draft.products.length ? "Nenhum produto encontrado." : "Vamos colocar sua pizza no cardápio."}</h3><p>{draft.products.length ? "Experimente outro nome ou categoria." : "Só precisa do nome e do preço para começar."}</p><button className="btn primary" onClick={() => editProduct("pizza")}><Plus size={18} />Adicionar manualmente</button></div>}</section>
              <p className="catalog-publish-hint"><Globe size={16} />Depois de editar preços ou disponibilidade, use <strong>Atualizar</strong> para aplicar ao cardápio.</p>
              <DailyPromotions data={draft} slug={active.slug} onChange={change} canShare={active.published&&!dirty&&active.revision===active.liveRevision}/>
              <DetailsPanel title="Bordas recheadas" subtitle={`${draft.crusts.length} opções · valor somado à pizza`}><div className="crust-list">{draft.crusts.map(crust => <div key={crust.id}><input aria-label="Nome da borda" value={crust.name} maxLength={60} onChange={e => change({ crusts: draft.crusts.map(row => row.id === crust.id ? { ...row, name: e.target.value } : row) })} /><input type="number" min="0" max="10000" step="0.01" aria-label={`Preço da borda ${crust.name}`} value={crust.price / 100} onChange={e => change({ crusts: draft.crusts.map(row => row.id === crust.id ? { ...row, price: asCents(e.target.value) } : row) })} /><button className="icon-btn" aria-label={`Excluir borda ${crust.name}`} onClick={() => change({ crusts: draft.crusts.filter(row => row.id !== crust.id) })}><Trash2 size={17} /></button></div>)}</div><button className="btn outline small" disabled={draft.crusts.length >= 12} onClick={() => change({ crusts: [...draft.crusts, { id: crypto.randomUUID(), name: "Nova borda", price: 0 }] })}><Plus size={17} />Adicionar borda</button><Field label="Preço da pizza meio a meio"><select value={draft.halfRule} onChange={e => change({ halfRule: e.target.value as "max" | "average" })}><option value="max">Valor do sabor mais caro</option><option value="average">Média dos dois sabores</option></select></Field></DetailsPanel>
              <DetailsPanel title="Categorias" subtitle="Organize pizzas, bebidas e combos"><div className="category-editor-list">{draft.categories.map((category, index) => <div key={category.id}><span className="category-number">{String(index + 1).padStart(2, "0")}</span><input aria-label={`Nome da categoria ${index + 1}`} value={category.name} maxLength={60} onChange={e => change({ categories: draft.categories.map(row => row.id === category.id ? { ...row, name: e.target.value } : row) })} /><small>{draft.products.filter(p => p.categoryId === category.id).length} produtos</small><button className="icon-btn" disabled={draft.categories.length === 1 || draft.products.some(p => p.categoryId === category.id)} aria-label={`Excluir categoria ${category.name}`} onClick={() => change({ categories: draft.categories.filter(row => row.id !== category.id) })}><Trash2 size={17} /></button></div>)}</div><div className="new-category"><input value={categoryName} onChange={e => setCategoryName(e.target.value)} maxLength={60} placeholder="Nova categoria" aria-label="Nome da nova categoria" /><button className="btn outline" disabled={categoryName.trim().length < 2 || draft.categories.length >= 20} onClick={() => { change({ categories: [...draft.categories, { id: crypto.randomUUID(), name: categoryName.trim() }] }); setCategoryName(""); }}><Plus size={16} />Adicionar</button></div><p className="field-hint">Mova os produtos para outra categoria antes de excluir uma categoria ocupada.</p></DetailsPanel>
              <DetailsPanel title="Cupom de desconto" subtitle={draft.coupon.enabled ? `${draft.coupon.code} · ${draft.coupon.percent}%` : "Opcional · você define o desconto e o pedido mínimo"}><ToggleRow label="Ativar cupom" text="Vale sobre os produtos, sem a taxa de entrega." value={draft.coupon.enabled} onChange={enabled => change({ coupon: { ...draft.coupon, enabled } })} /><Field label="Código do cupom"><input value={draft.coupon.code} maxLength={30} onChange={e => change({ coupon: { ...draft.coupon, code: e.target.value.toUpperCase().replace(/[^A-Z0-9_-]/g, "") } })} placeholder="Ex.: PIZZA10" /></Field><div className="form-row"><Field label="Desconto (%)"><input type="number" min="1" max="50" value={draft.coupon.percent} onChange={e => change({ coupon: { ...draft.coupon, percent: Number(e.target.value) } })} /></Field><MoneyField label="Pedido mínimo para usar" value={draft.coupon.minTotal} onChange={minTotal => change({ coupon: { ...draft.coupon, minTotal } })} /></div></DetailsPanel>
            </>}
            {tab === "store" && <>
              <button type="button" className="pizza-ai-shortcut" onClick={()=>setTab("studio")}><Sparkles size={24}/><span><b>Dê a sua cara ao cardápio</b><small>Crie logo, capa e textos com IA.</small></span><ArrowRight size={19}/></button>
              <div className="store-editor-grid simple-store-grid"><section className="panel-card"><div className="subsection-title"><h2>Nome e contato</h2><p>As informações que o cliente precisa para pedir.</p></div><Field label="Nome da pizzaria"><input value={draft.name} maxLength={100} onChange={e => change({ name: e.target.value })} placeholder="Pizzaria Bella Massa" /></Field><Field label="WhatsApp de pedidos" hint="Informe o número com DDD."><input type="tel" value={draft.whatsapp} maxLength={25} onChange={e => change({ whatsapp: e.target.value })} placeholder="(11) 99999-9999" /></Field><Field label="Horário de atendimento"><input value={draft.hours} maxLength={300} onChange={e => change({ hours: e.target.value })} placeholder="Terça a domingo, das 18h às 23h" /></Field><Field label="Endereço" hint="Obrigatório se houver retirada no local."><input value={draft.address} maxLength={200} onChange={e => change({ address: e.target.value })} placeholder="Rua, número e bairro" /></Field><Field label="Cidade e estado"><input value={draft.city} maxLength={80} onChange={e => change({ city: e.target.value })} placeholder="São Paulo, SP" /></Field></section><section className="panel-card"><div className="subsection-title"><h2>Entrega e pagamento</h2><p>O cliente vê os custos antes de finalizar.</p></div><ToggleRow label="Receber novos pedidos" text="Publique a alteração para abrir ou fechar os pedidos." value={draft.isOpen} onChange={isOpen => change({ isOpen })} /><ToggleRow label="Fazer entregas" text="O cliente informa o endereço no pedido." value={draft.deliveryEnabled} onChange={deliveryEnabled => change({ deliveryEnabled })} /><ToggleRow label="Oferecer retirada" text="No endereço da sua pizzaria." value={draft.pickupEnabled} onChange={pickupEnabled => change({ pickupEnabled })} /><div className="form-row"><MoneyField label="Taxa de entrega" value={draft.deliveryFee} onChange={deliveryFee => change({ deliveryFee })} /><Field label="Tempo estimado"><input value={draft.eta} maxLength={60} onChange={e => change({ eta: e.target.value })} placeholder="40–60 min" /></Field></div>{draft.deliveryEnabled&&<DeliveryAreas data={draft} onChange={change}/>}<span className="field-label">Formas de pagamento aceitas</span><div className="payment-options">{(["Pix", "Dinheiro", "Cartão de crédito", "Cartão de débito"] as const).map(payment => <label className="check-option" key={payment}><input type="checkbox" checked={draft.payments.includes(payment)} onChange={e => change({ payments: e.target.checked ? [...draft.payments, payment] : draft.payments.filter(p => p !== payment) })} />{payment}</label>)}</div><div className="pix-store-settings"><ToggleRow label="Receber Pix antes do preparo" text="O cliente paga e envia o comprovante. Você confere o banco e aprova no painel." value={draft.pix.enabled} onChange={enabled=>change({pix:{...draft.pix,enabled},payments:enabled&&!draft.payments.includes("Pix")?[...draft.payments,"Pix"]:draft.payments})}/>{draft.pix.enabled&&<><Field label="Tipo de chave Pix"><select value={draft.pix.type} onChange={e=>change({pix:{...draft.pix,type:e.target.value as RestaurantData["pix"]["type"],key:""}})}>{[["random","Chave aleatória"],["email","E-mail"],["phone","Celular"],["cpf","CPF"],["cnpj","CNPJ"]].map(([id,label])=><option key={id} value={id}>{label}</option>)}</select></Field><Field label="Chave Pix de recebimento" hint={draft.pix.type==="phone"?"Use +55, DDD e número, sem espaços.":"Copie a chave já cadastrada no aplicativo do seu banco."}><input maxLength={160} value={draft.pix.key} onChange={e=>change({pix:{...draft.pix,key:draft.pix.type==="email"?e.target.value.trim().toLowerCase():e.target.value.trim()}})} placeholder={draft.pix.type==="email"?"financeiro@suapizzaria.com.br":draft.pix.type==="phone"?"+5511999999999":"Sua chave Pix"}/></Field><Field label="Titular que aparece no banco"><input maxLength={100} value={draft.pix.recipient} onChange={e=>change({pix:{...draft.pix,recipient:e.target.value}})} placeholder="Nome do recebedor no banco"/></Field><p className="field-hint">Salve e publique para ativar. Pedidos já enviados mantêm a chave usada na compra.</p></>}</div><DetailsPanel title="Pedido mínimo" subtitle={draft.minOrder ? money(draft.minOrder) : "Sem valor mínimo"} compact><MoneyField label="Mínimo em produtos" value={draft.minOrder} onChange={minOrder => change({ minOrder })} /></DetailsPanel></section></div>
              <DetailsPanel title="Aparência do cardápio" subtitle={`${themes.find(t => t.id === draft.theme)?.name} · quatro estilos prontos`}><ThemeCards data={draft.products.length ? draft : { ...demoRestaurant(draft.theme), name: draft.name }} onSelect={id => change({ theme: id, accent: themes.find(t => t.id === id)!.color })} /><div className="simple-brand-fields"><div className="color-editor"><input type="color" aria-label="Cor do cardápio" value={draft.accent} onChange={e => change({ accent: e.target.value })} /><div><strong>Cor da sua marca</strong><span>{draft.accent.toUpperCase()}</span></div></div><button className="btn outline small" onClick={() => setPreviewOpen(true)}><Eye size={17} />Ver prévia</button></div><div className="design-media-grid"><div><span className="field-label">Logo · opcional</span><ImageUploader id={active.id} value={draft.logo} onChange={logo => change({ logo })} label="Enviar logo" square /></div><div><span className="field-label">Capa · opcional</span><ImageUploader id={active.id} value={draft.cover} onChange={cover => change({ cover })} label="Enviar capa" /></div></div></DetailsPanel>
              <DetailsPanel title="Apresentação e Instagram" subtitle="Opcional · conte o que torna sua pizza especial"><Field label="Frase do cardápio"><input value={draft.tagline} maxLength={120} onChange={e => change({ tagline: e.target.value })} placeholder="Da nossa casa, para a sua." /></Field><Field label="Sobre sua pizzaria"><textarea rows={3} value={draft.description} maxLength={700} onChange={e => change({ description: e.target.value })} /></Field><Field label="Instagram"><input value={draft.instagram} maxLength={80} onChange={e => change({ instagram: e.target.value })} placeholder="@suapizzaria" /></Field></DetailsPanel>
              <DetailsPanel title="Minha conta e assinatura" subtitle="Seu plano e a publicação do cardápio"><BillingControls initialPlan={active.plan} /><p className="panel-description">Endereço reservado: <strong>/p/{active.slug}</strong></p>{active.published && <div className="pause-panel"><div><h3>Pausar publicação</h3><p>O link deixa de exibir o cardápio até você publicar novamente.</p></div><button className="btn outline small" onClick={() => publish(false)}><Pause size={17} />Pausar</button></div>}</DetailsPanel>
            </>}
          </fieldset>
          {tab==="studio"&&draft.products.length===0&&<section className="first-run-assistant"><span className="eyebrow">PRIMEIROS PASSOS · SUA PIZZARIA</span><h2>A IA ajuda a criar o visual; seu cardápio começa pela foto.</h2><p>Descreva o estilo abaixo e confira a prévia. Depois, envie as fotos do cardápio: a leitura acontece no seu aparelho e mostra produtos e preços para revisão, sem gastar gerações de imagem.</p><button className="btn outline" type="button" onClick={()=>setTab("menu")}><Upload size={17}/>Enviar fotos do cardápio</button></section>}
          {tab==="studio"&&<StudioChat key={active.id} data={draft} restaurantId={active.id} onNavigate={section=>setTab(section)} initialMessage={firstRun?.restaurantId===active.id?firstRun.idea:""} onPrepare={async()=>{const row=await save();return row?restaurantSchema.parse(JSON.parse(row.data)):null;}} onApply={patch=>{if(saving||activeIdRef.current!==active.id)return;change(patch);setToast("Pronto! Publique para seus clientes verem.");}}/>}
          {dirty && <div className="unsaved-bar simple-unsaved"><div><span className="unsaved-dot" /><p><strong>Alterações no rascunho</strong><span>{active.published ? "Atualize para o cliente ver as mudanças." : "Publique quando estiver pronto."}</span></p></div><div><button className="text-button" disabled={saving} onClick={save}>Guardar rascunho</button><button className="btn dark" disabled={saving} onClick={() => publish()}>{saving ? <Spinner /> : <Check size={17} />}{active.published ? "Salvar e atualizar" : "Publicar"}</button></div></div>}
        </>}
      </main><footer className="dashboard-footer"><span>pedido.on <small>Seu cardápio. Seus pedidos.</small></span><a href="/calculadora">Calculadora grátis <ArrowUpRight size={13}/></a></footer>
    </div>
    <nav className="simple-mobile-nav" aria-label="Navegação rápida">{navigation.map(item => <button key={item.id} className={tab === item.id ? "active" : ""} aria-current={tab === item.id ? "page" : undefined} onClick={() => setTab(item.id)}><item.icon size={21} /><span>{item.id==="studio"?"Criar com IA":item.label}</span></button>)}</nav>
    <Modal open={createOpen} onClose={() => { if(restaurants.length)setCreateOpen(false); }} title="Vamos montar sua pizzaria com IA"><CreateRestaurant theme={initialTheme} plan={initialPlan} onCreate={(row,idea) => { setRestaurants(old => [...old, row]); setActiveId(row.id); setFirstRun({restaurantId:row.id,idea}); setCreateOpen(false); setTab("studio"); setToast("Sua pizzaria está criada. Prepare o visual e envie as fotos do cardápio."); }} /></Modal>
    <Modal open={previewOpen} onClose={() => setPreviewOpen(false)} title="Veja como seu cliente pede" wide><div className="full-menu-preview"><Menu data={draft} preview /></div></Modal>
    <Modal open={shareOpen} onClose={() => setShareOpen(false)} title={active?.published ? "Seu cardápio pronto para compartilhar" : "Publique para começar a vender"}><div className="share-modal"><span className="success-mark"><CheckCircle2 size={42} /></span><h3>{active?.published ? "Leve seu link até os clientes." : "Seu endereço já está reservado."}</h3><p>{active?.published ? "Coloque na bio do Instagram e compartilhe pelo WhatsApp." : "Cadastre os produtos e publique para ativar o link."}</p><input readOnly aria-label="Link do cardápio" value={typeof window !== "undefined" ? `${location.origin}/p/${active?.slug || ""}` : `/p/${active?.slug || ""}`} onFocus={e => e.target.select()} /><div><button className="btn primary" onClick={copyLink}><Copy size={17} />Copiar link</button>{active?.published && <a className="btn whatsapp-btn" href={`https://wa.me/?text=${encodeURIComponent(`Confira nosso cardápio e monte seu pedido: ${typeof window !== "undefined" ? location.origin : ""}/p/${active.slug}`)}`} target="_blank" rel="noopener noreferrer"><MessageCircle size={18} />Compartilhar</a>}</div>{active?.published && <a className="text-button" href={`/p/${active.slug}`} target="_blank" rel="noopener noreferrer">Abrir meu cardápio <ArrowUpRight size={17} /></a>}</div></Modal>
    <Modal open={!!productEdit} onClose={() => setProductEdit(null)} title={productEdit?.name ? "Editar produto" : productEdit?.kind === "pizza" ? "Adicionar pizza" : "Adicionar bebida ou combo"}>{productEdit && active && <ProductEditor key={productEdit.id} initial={productEdit} restaurantId={active.id} categories={draft.categories} onSave={saveProduct} onDelete={() => { change({ products: draft.products.filter(p => p.id !== productEdit.id),promotions:(draft.promotions||[]).filter(p=>p.productId!==productEdit.id) }); setProductEdit(null); }} />}</Modal>
    <Modal open={!!orderDetail} onClose={() => setOrderDetail(null)} title={`Pedido #${orderDetail?.id.slice(0, 8).toUpperCase() || ""}`}>{orderDetail && <OrderDetails key={orderDetail.id} order={orderDetail} busy={!!updatingOrder} error={error} onAction={details=>updateOrder(orderDetail,details)} />}</Modal>
    {toast && <div className="toast" role="status"><Check size={18} />{toast}</div>}
  </div>;
}

function DetailsPanel({ title, subtitle, children, compact = false }: { title: string; subtitle: string; children: ReactNode; compact?: boolean }) {
  return <details className={`details-panel ${compact ? "compact" : ""}`}><summary><div><strong>{title}</strong><span>{subtitle}</span></div><ChevronDown size={19} /></summary><div className="details-panel-content">{children}</div></details>;
}
function ShoppingIcon(){return <Package size={18}/>;}
function InfoIcon(){return <AlertCircle size={20}/>;}
function Field({label,hint,children}:{label:string;hint?:string;children:ReactNode}){return <label className="field"><span>{label}</span>{children}{hint&&<small className="field-hint">{hint}</small>}</label>;}
function MoneyField({label,value,onChange}:{label:string;value:number;onChange:(v:number)=>void}){return <Field label={label}><div className="money-input"><span>R$</span><input type="number" min="0" max="10000" step="0.01" value={value/100} onChange={e=>onChange(asCents(e.target.value))}/></div></Field>;}
function ToggleRow({label,text,value,onChange}:{label:string;text:string;value:boolean;onChange:(v:boolean)=>void}){return <div className="toggle-row"><div><strong>{label}</strong><p>{text}</p></div><button type="button" role="switch" aria-checked={value} aria-label={label} className={`toggle ${value?"on":""}`} onClick={()=>onChange(!value)}><span/></button></div>;}
function ImageUploader({id,value,onChange,label,square=false}:{id:string;value:string;onChange:(url:string)=>void;label:string;square?:boolean}){const [busy,setBusy]=useState(false),[error,setError]=useState("");async function upload(file?:File){if(!file)return;if(file.size>2097152){setError("A imagem deve ter até 2 MB.");return;}setError("");setBusy(true);try{const form=new FormData();form.append("file",file);const res=await fetch(`/api/restaurants/${id}/media`,{method:"POST",body:form}),body=await res.json() as {url:string;error?:string};if(!res.ok)throw new Error(body.error);onChange(body.url);}catch(e){setError(e instanceof Error?e.message:"Não foi possível enviar a imagem.");}finally{setBusy(false);}}return <div className={`image-uploader ${square?"square":""}`}>{value?<div className="uploaded-image"><img src={value} alt="Imagem enviada"/><button type="button" className="icon-btn" aria-label="Remover imagem" onClick={()=>onChange("")}><Trash2 size={16}/></button></div>:<div className="upload-placeholder"><ImagePlus size={32}/><strong>{label}</strong><span>JPG, PNG ou WebP · até 2 MB</span></div>}<label className="upload-trigger btn outline small">{busy?<Spinner/>:<Upload size={15}/>} {busy?"Enviando...":value?"Trocar imagem":label}<input type="file" accept="image/jpeg,image/png,image/webp" disabled={busy} onChange={e=>{upload(e.target.files?.[0]);e.target.value="";}}/></label>{error&&<p className="field-error" role="alert">{error}</p>}</div>;}
function CreateRestaurant({ theme, plan, onCreate }: { theme: ThemeId; plan: string; onCreate: (record: RestaurantRecord,vision:string) => void }) {
  const [name, setName] = useState(""), [whatsapp, setWhatsapp] = useState(""), [slug, setSlug] = useState(""), [manualSlug, setManualSlug] = useState(false),[vision,setVision]=useState("");
  const selected=theme;
  const [busy, setBusy] = useState(false), [error, setError] = useState("");
  async function create(event: FormEvent) {
    event.preventDefault(); setError("");
    if (!slugSchema.safeParse(slug).success) { setError("Escolha um endereço com ao menos 3 caracteres. Comece com uma letra e use letras, números e hífens."); return; }
    const phone = phoneNumber(whatsapp);
    if (phone.length < 12 || phone.length > 15) { setError("Confira seu WhatsApp com DDD."); return; }
    setBusy(true);
    try { const body = await api("/api/restaurants", "POST", { name, whatsapp, slug, theme: selected, plan }); onCreate(body.restaurant,vision.trim()||`Quero um visual profissional e textos claros para a pizzaria ${name.trim()}. Sugira uma identidade própria sem alterar ingredientes nem preços.`); }
    catch (e) { setError(e instanceof Error ? e.message : "Não foi possível criar seu cardápio."); }
    finally { setBusy(false); }
  }
  return <form className="create-shop fast-create" onSubmit={create}><p className="create-intro">Conte como imagina a loja. O assistente prepara uma prévia e você importa seu cardápio por foto, sem digitar todos os sabores.</p><fieldset disabled={busy} className="editor-fieldset"><Field label="Nome da pizzaria"><input required minLength={2} maxLength={100} value={name} autoComplete="organization" onChange={e=>{setName(e.target.value);if(!manualSlug)setSlug(slugify(e.target.value));}} placeholder="O nome da sua pizzaria"/></Field><Field label="WhatsApp de pedidos"><input required type="tel" maxLength={25} autoComplete="tel" value={whatsapp} onChange={e=>setWhatsapp(e.target.value)} placeholder="(11) 99999-9999"/></Field><Field label="Endereço do seu cardápio" hint="Este será o link que você compartilha com os clientes."><div className="slug-input"><span>/p/</span><input required minLength={3} maxLength={60} value={slug} onChange={e=>{setManualSlug(true);setSlug(slugify(e.target.value));}} placeholder="nome-da-pizzaria"/></div></Field><Field label="Como você imagina o visual da sua pizzaria?" hint="Opcional. Você confere a prévia antes de publicar."><textarea rows={3} maxLength={1200} value={vision} onChange={e=>setVision(e.target.value)} placeholder="Ex.: estilo preto e vermelho, pizzaria artesanal, logo com forno a lenha e textos curtos."/></Field></fieldset>{error&&<p className="field-error" role="alert">{error}</p>}<button type="submit" className="btn primary full" disabled={busy}>{busy?<Spinner/>:<ArrowRight size={18}/>}Começar com o assistente</button><p className="create-no-charge">Você decide quando publicar.</p></form>;
}
function ProductEditor({initial,restaurantId,categories,onSave,onDelete}:{initial:Product;restaurantId:string;categories:RestaurantData["categories"];onSave:(p:Product)=>void;onDelete:()=>void}){const [product,setProduct]=useState(initial),[error,setError]=useState(""),[confirmDelete,setConfirmDelete]=useState(false);function patch(v:Partial<Product>){setProduct(old=>({...old,...v}));}function submit(e:FormEvent){e.preventDefault();if(product.name.trim().length<2){setError("Informe o nome do produto.");return;}if(product.kind==="pizza"?!Object.values(product.sizes).some(v=>v>0):product.price<=0){setError("Cadastre um preço maior que zero. Na pizza, preencha ao menos um tamanho.");return;}onSave({...product,name:product.name.trim()});}return <form className="product-editor" onSubmit={submit}><div className="segmented"><button type="button" className={product.kind==="pizza"?"active":""} onClick={()=>patch({kind:"pizza"})}><Pizza size={17}/>Pizza</button><button type="button" className={product.kind==="simple"?"active":""} onClick={()=>patch({kind:"simple"})}><Package size={17}/>Bebida ou combo</button></div><Field label="Nome do produto"><input required minLength={2} maxLength={100} value={product.name} onChange={e=>patch({name:e.target.value})} placeholder="Ex.: Margherita da casa"/></Field><Field label="Categoria"><select value={product.categoryId} onChange={e=>patch({categoryId:e.target.value})}>{categories.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></Field>{product.kind==="pizza"?<><span className="field-label">Preços por tamanho</span><div className="pizza-prices">{(["p","m","g"] as const).map(s=><MoneyField key={s} label={`${s.toUpperCase()} · ${s==="p"?"4":s==="m"?"6":"8"} fatias`} value={product.sizes[s]} onChange={price=>patch({sizes:{...product.sizes,[s]:price}})}/>)}</div><p className="field-hint">Deixe zero nos tamanhos que você não oferece.</p></>:<MoneyField label="Preço do produto / combo" value={product.price} onChange={price=>patch({price})}/>}<DetailsPanel title="Foto e descrição" subtitle="Opcional · pode adicionar depois"><Field label="Descrição"><textarea rows={3} maxLength={600} value={product.description} onChange={e=>patch({description:e.target.value})} placeholder="Conte os ingredientes e o que torna esse sabor especial."/></Field><span className="field-label">Foto do produto <small>Opcional</small></span><ImageUploader id={restaurantId} value={product.image} onChange={image=>patch({image})} label="Enviar foto do produto"/></DetailsPanel><ToggleRow label="Disponível no cardápio" text="Pause os produtos que acabaram." value={product.enabled} onChange={enabled=>patch({enabled})}/><ToggleRow label="Destaque da casa" text="Mostre no início. Uma boa opção para o combo da casa." value={product.featured} onChange={featured=>patch({featured})}/>{error&&<div className="field-error" role="alert">{error}</div>}<div className="product-editor-footer">{initial.name?<button className="text-button danger" type="button" onClick={()=>setConfirmDelete(true)}><Trash2 size={15}/>Excluir produto</button>:<small>Será adicionado ao seu rascunho.</small>}<button className="btn primary" type="submit"><Check size={17}/>Salvar produto</button></div>{confirmDelete&&<div className="delete-confirm"><p>Excluir <strong>{initial.name}</strong> do rascunho?</p><button type="button" className="btn outline small" onClick={()=>setConfirmDelete(false)}>Manter produto</button><button type="button" className="btn primary small" onClick={onDelete}>Excluir</button></div>}</form>;}
